blog_Malibu-Package.html.text:
offer-detail .carousel-control-prev, .offer-detail .carousel-control-next {
top:10% !important;
}
#tabAdultContent {
background: white;
}
.gallery-filter .btn-outline-primary{
color: unset !important;
border-color: unset !important;
}
.gallery-filter .btn{
display: unset !important;
color: unset !important;
border: unset !important;
padding: unset !important;
margin-bottom: 0.5rem !important;
font-size: 1.25rem !important;
}
.gallery-filter .btn-outline-primary:active,.gallery-filter .btn-outline-primary:hover{
color: var(--main-color-orange) !important;
background-color: unset !important;
}
#modal_hotelroom_info .description{
color: var(--main-color-orange) !important;
}
.btn-check:focus + .btn-outline-primary, .btn-outline-primary:focus
{
box-shadow: unset !important;
}
.abs-img-2 {
bottom: 20%;
right: 5%;
overflow: hidden;
z-index:150;
}
.abs-img-2:hover .circle {
background-color: var(--main-color-orange);
}
.abs-img-2:hover .circle h5{
color: black;
}
.abs-img-2 .circle h5{
color: var(--main-color-orange);
}
.abs-img-2 .circle {
background-color: black;
border-radius: 50%;
display: inline-block;
height: 100px;
width: 100px;
padding: 16px;
}
.abs-img {
position: absolute;
}
.abs-img-2::before {
inset: 0;
background-image: url(https://s3-north1.viettelidc.com.vn/enet/io/files/sites/2/badge-2-bg.png);
background-repeat: no-repeat;
background-size: contain;
animation: rotate360 15s linear infinite;
}
.has-before::before, .has-after::after {
content: "";
position: absolute;
}
@keyframes rotate360 {
0% { transform: rotate(0); }
100% { transform: rotate(1turn); }
}
.btn-check:checked + .btn-secondary, .btn-check:active + .btn-secondary, .btn-secondary:active, .btn-secondary.active, .show > .btn-secondary.dropdown-toggle {
background-color: var(--main-color-orange) !important;
border-radius: 0;
}
.overlap-1000{
z-index: 1000;
}
.fs-13{
font-size: 0.9rem;
}
.fw-200{
font-weight: 200;
}
.fw-600{
font-weight: 600 !important;
}
.fs-125{
font-size: 1.25rem;
}
.bg-checkrate {
background: #f2f2f2;
}
.certificate-section .swiper-button-next, .certificate-section .swiper-container-rtl .swiper-button-prev {
background-image: url(/files/sites/70/left-arrow.svg);
right: -8%;
left: auto;
transform: rotate(180deg);
}
.certificate-section .swiper-button-prev, .certificate-section .swiper-container-rtl .swiper-button-next {
background-image: url(/files/sites/70/left-arrow.svg);
left: -8%;
right: auto;
}
.certificate-section .swiper-button-next, .certificate-section .swiper-button-prev{
top: 10% !important;
width:8% !important;
height:100% !important;
transition: .1s ease-out;
}
.bg-surface-secondary {
background: #f2f2f2 !important;
}
.nav-link:hover, .nav-link.active {
color: var(--main-color-orange) !important;
}
.position-header {
position: absolute !important;
}
.gallery-filter button:nth-child(1){
text-transform: uppercase;
}
.nav-pills .nav-link.active, .nav-pills .show > .nav-link{
background-color: unset !important;
}
.dine-box:hover .background {
z-index: 1;
}
#checkrateFormModal .checkin, #checkrateFormModal .checkout, #checkrateFormModal .guest {
display: flex;
font-weight: 200;
font-size: 24px;
margin-right: 7px;
background-color: transparent;
align-items:center;
}
#pills-tab{
gap: 2.5rem;
}
.nav-checkrate-month{
text-transform: uppercase;
}
.nav-checkrate-date {
font-size: 3rem;
padding-left:10px;
}
.nav-checkrate-adult{
font-size: 3rem;
}
.mg-booking-form .nav-tabs > li.mg-step-done > a span.mg-bs-tab-num {
border-color: var(--main-color-orange) !important;
background-color: var(--main-color-orange) !important;
}
.mg-sec-left-title:after, .mg-widget-title:after{
background-color: var(--main-color-orange) !important;
}
.mg-sec-left-title, .mg-widget-title{
color: var(--main-color-orange) !important;
}
.mg-booking-form .mg-widget{
background-color: #f2f2f2 !important;
}
.mg-booking-form .nav-tabs > li > a span.mg-bs-bar:after{
background-color: var(--main-color-orange) !important;
}
.mg-widget .mg-widget-cart-row strong {
color: var(--main-color-orange) !important;
}
.mg-widget .mg-widget-title {
color: black !important;
}
.social-fixed {
top: 35%;
right: 0;
position: fixed;
z-index: 10002;
}
.social-fixed .bi {
width: 40px;
height: 41px;
font-size: 25px;
text-align: center;
text-decoration: none;
display: block;
/*border: 1px dashed #a5a5a5;
border-right: 0 !important;
border-top-left-radius: 5px;
border-bottom-left-radius: 5px;*/
}
.social-fixed .bi:hover {
opacity: 0.7;
}
.social-fixed .bi-messenger {
background: #00A4FF;
color: white;
}
.social-fixed .bi-zalo {
height: 31px;
width: 30px;
margin-bottom: 5px;
}
@media only screen and (max-width: 1399.98px){
.roomSuiteAll .carousel .carousel-inner .carousel-item img {
max-height: 24rem;
}
@media only screen and (min-width: 1399.98px) and (max-width: 1999.98px){
.roomSuiteAll .carousel .carousel-inner .carousel-item img {
max-height: 24rem;
}
@media only screen and (min-width: 1999.98px){
.roomSuiteAll .carousel .carousel-inner .carousel-item img {
max-height: 37rem;
}
